                 {/* SLIDE PRESENTATION LAYER */}
                 {isPresentationMode && selectedFileName && (
                   <div className="absolute inset-0 z-40 bg-white flex flex-col items-center justify-center text-slate-900 animate-in fade-in transition-all">
