                    </td>
                    <td className="px-8 py-5 text-center font-black text-slate-600 text-xs tabular-nums">{c.inscritos}</td>
                    <td className="px-8 py-5 text-[10px] font-bold text-slate-400 uppercase tracking-widest italic">{c.categoria}</td>
                    <td className="px-8 py-5">
                      <div className="flex items-center gap-2">
                        <div className={`w-2 h-2 rounded-full ${c.status === 'ativo' ? 'bg-emerald-500 animate-pulse' : 'bg-slate-300'}`}></div>
                        <span className={`text-[10px] font-black uppercase ${c.status === 'ativo' ? 'text-emerald-700' : 'text-slate-500'}`}>{c.status}</span>
                      </div>
                    </td>
                    <td className="px-8 py-5 text-center">
                      <button onClick={() => { setSelectedCourse(c); setSubView('course_details'); }} className="p-2.5 bg-white border border-slate-100 rounded-xl text-indigo-600 shadow-sm hover:scale-110 transition-all"><ArrowUpRight size={16}/></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    );
  }

  // TELA: DASHBOARD PRINCIPAL
  const stats = [
    { label: 'Alunos Ativos', value: totalStudents.toString(), icon: <Users size={20} />, trend: '+12.5%', color: 'indigo', action: () => onNavigate('alunos') },
    { label: 'Certificados', value: certificates.length.toString(), icon: <FileBadge size={20} />, trend: '+4.1%', color: 'amber', action: () => setSubView('certificates') },
