           <div className="bg-white p-10 rounded-[3rem] border border-slate-200 shadow-sm space-y-8">
              <div className="flex items-center gap-3"><div className="p-2.5 bg-slate-900 text-white rounded-xl"><TrendingUp size={16}/></div><h3 className="text-xs font-black text-slate-800 uppercase tracking-widest italic">Atalhos Master</h3></div>
              <div className="space-y-3">
                 <button onClick={() => onNavigate('professor', 'frequencia')} className="w-full flex items-center justify-between px-8 py-5 rounded-2xl bg-slate-50 hover:bg-indigo-600 hover:text-white transition-all text-[10px] font-black uppercase group italic">Frequência Mensal <ChevronRight size={14}/></button>
                 <button onClick={() => onNavigate('professor', 'relatorio')} className="w-full flex items-center justify-between px-8 py-5 rounded-2xl bg-slate-50 hover:bg-indigo-600 hover:text-white transition-all text-[10px] font-black uppercase group italic">Desempenho Acadêmico <ChevronRight size={14}/></button>
                 <button onClick={() => onNavigate('professor', 'feedback')} className="w-full flex items-center justify-between px-8 py-5 rounded-2xl bg-slate-50 hover:bg-indigo-600 hover:text-white transition-all text-[10px] font-black uppercase group italic">Feedback Discente <ChevronRight size={14}/></button>
