        <div className="space-y-6">
           <div className="bg-slate-900 text-white p-10 rounded-[3rem] shadow-2xl relative overflow-hidden group">
              <div className="relative z-10">
                <div className="flex items-center gap-3 mb-6"><div className="w-2 h-2 bg-rose-500 rounded-full animate-ping"></div><h3 className="text-xs font-black uppercase tracking-widest italic">Live Classroom</h3></div>
                <h3 className="text-3xl font-black mb-2 uppercase tracking-tighter italic leading-none">Aulas Ao Vivo</h3>
                <p className="text-slate-400 text-[10px] font-medium mb-10 leading-relaxed uppercase tracking-widest italic">Transmissão em tempo real.</p>
