export default DashboardView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { collection, query, getDocs, orderBy, where, doc, getDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { Course, MainView, ProfessorSubView } from '../types';
import { 
  Users, FileBadge, Activity, ArrowUpRight, TrendingUp, Tv, ArrowLeft, 
  Search, Filter, Download, Calendar, BookOpen, ChevronRight, ShieldCheck,
  Eye, Printer, X
} from 'lucide-react';

interface DashboardViewProps {
  onNavigate: (main: MainView, sub?: ProfessorSubView) => void;
}

type DashboardSubView = 'main' | 'all_courses' | 'course_details' | 'certificates';

const DashboardView: React.FC<DashboardViewProps> = ({ onNavigate }) => {
  const [courses, setCourses] = useState<Course[]>([]);
  const [totalStudents, setTotalStudents] = useState(0);
  const [loading, setLoading] = useState(true);
  const [subView, setSubView] = useState<DashboardSubView>('main');
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Estados para Certificados
  const [certFilter, setCertFilter] = useState('');
  const [dateRange, setDateRange] = useState('all');
  const [customDate, setCustomDate] = useState('');
  const [certificates, setCertificates] = useState<any[]>([]);
  const [previewCert, setPreviewCert] = useState<any>(null);
  const [schoolSettings, setSchoolSettings] = useState<any>(null);

  const dateInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const qCourses = query(collection(db, 'cursos'), orderBy('createdAt', 'desc'));
        const snapCourses = await getDocs(qCourses);
        setCourses(snapCourses.docs.map(doc => ({ id: doc.id, ...doc.data() } as Course)));

        const qStudents = query(collection(db, 'users'), where('role', '==', 'aluno'));
        const snapStudents = await getDocs(qStudents);
        setTotalStudents(snapStudents.size);

        if (auth.currentUser) {
          const directorDoc = await getDoc(doc(db, 'users', auth.currentUser.uid));
          if (directorDoc.exists()) setSchoolSettings(directorDoc.data());
        }

        const qCerts = query(collection(db, 'certificates'), orderBy('issuedAt', 'desc'));
        const snapCerts = await getDocs(qCerts);

        if (snapCerts.empty) {
          setCertificates([
            { id: 'EB-7721-A', studentName: 'Carlos Eduardo Silva', courseName: 'Teologia Sistemática I', issuedAt: new Date(2023, 11, 15), professorName: 'Prof. Dr. Arnaldo', code: 'VALID-990' },
            { id: 'EB-7722-B', studentName: 'Maria das Graças', courseName: 'História do Cristianismo', issuedAt: new Date(2024, 0, 10), professorName: 'Prof. Lucas Mendes', code: 'VALID-991' },
            { id: 'EB-7723-C', studentName: 'Ricardo Oliveira', courseName: 'Hermenêutica Avançada', issuedAt: new Date(2024, 2, 5), professorName: 'Prof. Paulo Silas', code: 'VALID-992' },
          ]);
        } else {
          setCertificates(snapCerts.docs.map(d => ({ id: d.id, ...d.data(), issuedAt: d.data().issuedAt?.toDate() })));
        }

      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const filteredAllCourses = useMemo(() => {
    return courses.filter(c => 
      c.nome.toLowerCase().includes(searchTerm.toLowerCase()) ||
      c.professorResponsavel.toLowerCase().includes(searchTerm.toLowerCase()) ||
      c.categoria.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [courses, searchTerm]);

  const filteredCerts = useMemo(() => {
    let list = certificates.filter(c => 
      c.studentName.toLowerCase().includes(certFilter.toLowerCase()) || 
      c.id.toLowerCase().includes(certFilter.toLowerCase())
    );

    const now = new Date();
    if (dateRange === '30') {
      const thirtyDaysAgo = new Date();
      thirtyDaysAgo.setDate(now.getDate() - 30);
      list = list.filter(c => c.issuedAt >= thirtyDaysAgo);
    } else if (dateRange === '90') {
      const ninetyDaysAgo = new Date();
      ninetyDaysAgo.setDate(now.getDate() - 90);
      list = list.filter(c => c.issuedAt >= ninetyDaysAgo);
    } else if (dateRange === 'custom' && customDate) {
      const selected = new Date(customDate);
      list = list.filter(c => 
        c.issuedAt.getFullYear() === selected.getFullYear() &&
        c.issuedAt.getMonth() === selected.getMonth() &&
        c.issuedAt.getDate() === selected.getDate()
      );
    }
    return list;
  }, [certificates, certFilter, dateRange, customDate]);

  // Função para exportar os cursos filtrados para CSV
  const exportCoursesToCSV = () => {
    if (filteredAllCourses.length === 0) {
      alert("Não há dados para exportar.");
      return;
    }

    const headers = ["ID", "Nome da Disciplina", "Professor Titular", "Inscritos", "Categoria", "Nível", "Status"];
    const rows = filteredAllCourses.map(c => [
      c.id,
      `"${c.nome.replace(/"/g, '""')}"`,
      `"${c.professorResponsavel.replace(/"/g, '""')}"`,
      c.inscritos,
      c.categoria,
      c.nivelDificuldade,
      c.status
    ]);

    const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
    const blob = new Blob(["\ufeff" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    const url = URL.createObjectURL(blob);

    link.setAttribute("href", url);
    link.setAttribute("download", `Matriz_Academica_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handlePrintAction = (cert: any) => {
    setPreviewCert(cert);
    setTimeout(() => window.print(), 300);
  };

  const handleDownloadAction = (cert: any) => {
    setPreviewCert(cert);
    setTimeout(() => window.print(), 300);
  };

  if (loading && subView === 'main') {
    return (
      <div className="h-full flex items-center justify-center p-20">
        <div className="h-8 w-8 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div>
      </div>
    );
  }

  // SUB-VIEW: LISTAGEM DE CERTIFICADOS
  if (subView === 'certificates') {
    return (
      <div className="space-y-6 animate-in slide-in-from-right duration-500">
        <header className="flex items-center gap-4">
          <button onClick={() => setSubView('main')} className="p-2 hover:bg-slate-200 rounded-full transition-colors bg-white shadow-sm border border-slate-200"><ArrowLeft size={20}/></button>
          <div>
            <h1 className="text-2xl font-black text-slate-900 uppercase tracking-tighter italic">Arquivo de Certificações</h1>
            <p className="text-slate-500 text-sm font-medium italic">Registros oficiais de conclusão acadêmica.</p>
          </div>
        </header>

        <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden">
          <div className="p-8 border-b border-slate-100 bg-slate-50/50 flex flex-col md:flex-row justify-between items-center gap-4">
             <div className="relative w-full max-w-md">
                <Search size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                <input 
                  type="text" 
                  value={certFilter}
                  onChange={(e) => setCertFilter(e.target.value)}
                  placeholder="Nome do aluno ou código do documento..." 
                  className="w-full pl-12 pr-4 py-3 bg-white border border-slate-200 rounded-2xl text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all shadow-inner" 
                />
             </div>
             <div className="flex items-center gap-3">
                <select 
                  value={dateRange}
                  onChange={(e) => setDateRange(e.target.value)}
                  className="px-6 py-3 bg-white border border-slate-200 rounded-xl text-[10px] font-black uppercase text-slate-600 outline-none shadow-sm focus:ring-1 focus:ring-indigo-500"
                >
                   <option value="all">Todo o Período</option>
                   <option value="30">Últimos 30 dias</option>
                   <option value="90">Últimos 90 dias</option>
                   <option value="custom">Data Específica</option>
                </select>

                <div className="relative">
                  <input 
                    type="date" 
                    ref={dateInputRef}
                    value={customDate}
                    onChange={(e) => {
                      setCustomDate(e.target.value);
                      setDateRange('custom');
                    }}
                    className="absolute inset-0 opacity-0 pointer-events-none" 
                  />
                  <button 
                    onClick={() => dateInputRef.current?.showPicker()}
                    className={`p-3 bg-white border rounded-xl transition-all shadow-sm ${dateRange === 'custom' ? 'border-indigo-600 text-indigo-600' : 'border-slate-200 text-slate-400 hover:text-indigo-600 hover:border-indigo-200'}`}
                  >
                    <Calendar size={18}/>
                  </button>
                </div>
             </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-slate-50/80 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] border-b border-slate-100 italic">
                <tr>
                  <th className="px-8 py-5">Identificação / Aluno</th>
                  <th className="px-8 py-5">Curso Finalizado</th>
                  <th className="px-8 py-5">Data Emissão</th>
                  <th className="px-8 py-5">Status Jurídico</th>
                  <th className="px-8 py-5 text-center">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {filteredCerts.map(c => (
                  <tr key={c.id} className="hover:bg-indigo-50/10 transition-colors group">
                    <td className="px-8 py-5">
                      <div className="flex flex-col">
                         <span className="font-black text-slate-900 text-xs uppercase italic tracking-tight">{c.id}</span>
                         <span className="text-[9px] text-indigo-500 font-bold uppercase mt-0.5">{c.studentName}</span>
                      </div>
                    </td>
                    <td className="px-8 py-5 font-black text-slate-600 text-xs uppercase italic">{c.courseName}</td>
                    <td className="px-8 py-5 text-xs font-bold text-slate-400 tabular-nums">{c.issuedAt.toLocaleDateString('pt-BR')}</td>
                    <td className="px-8 py-5">
                       <span className="flex items-center gap-1.5 text-emerald-600 font-black uppercase text-[9px] tracking-widest"><ShieldCheck size={12}/> Válido</span>
                    </td>
                    <td className="px-8 py-5">
                       <div className="flex items-center justify-center gap-2">
                          <button onClick={() => setPreviewCert(c)} title="Visualizar" className="p-2.5 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all shadow-sm active:scale-90"><Eye size={14}/></button>
                          <button onClick={() => handlePrintAction(c)} title="Imprimir" className="p-2.5 bg-slate-50 text-slate-600 rounded-xl hover:bg-slate-900 hover:text-white transition-all shadow-sm active:scale-90"><Printer size={14}/></button>
                          <button onClick={() => handleDownloadAction(c)} title="Download" className="p-2.5 bg-emerald-50 text-emerald-600 rounded-xl hover:bg-emerald-600 hover:text-white transition-all shadow-sm active:scale-90"><Download size={14}/></button>
                       </div>
                    </td>
                  </tr>
                ))}
                {filteredCerts.length === 0 && (
                   <tr>
                    <td colSpan={5} className="p-20 text-center text-[10px] font-black uppercase text-slate-300 italic tracking-[0.3em]">Nenhum certificado encontrado para o filtro selecionado.</td>
                   </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>

        {/* MODAL DE PREVIEW DO CERTIFICADO */}
        {previewCert && (
