export default DashboardView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { collection, query, getDocs, orderBy, where, doc, getDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { Course, MainView, ProfessorSubView } from '../types';
import { 
  Users, FileBadge, Activity, ArrowUpRight, TrendingUp, Tv, ArrowLeft, 
  Search, Filter, Download, Calendar, BookOpen, ChevronRight, ShieldCheck,
  Eye, Printer, X, BarChart3, Layers, Star, GraduationCap, Clock
} from 'lucide-react';

interface DashboardViewProps {
  onNavigate: (main: MainView, sub?: ProfessorSubView) => void;
}

type DashboardSubView = 'main' | 'all_courses' | 'course_details' | 'certificates';

const DashboardView: React.FC<DashboardViewProps> = ({ onNavigate }) => {
  const [courses, setCourses] = useState<Course[]>([]);
  const [totalStudents, setTotalStudents] = useState(0);
  const [loading, setLoading] = useState(true);
  const [subView, setSubView] = useState<DashboardSubView>('main');
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Estados para Certificados
  const [certFilter, setCertFilter] = useState('');
  const [dateRange, setDateRange] = useState('all');
  const [customDate, setCustomDate] = useState('');
  const [certificates, setCertificates] = useState<any[]>([]);
  const [previewCert, setPreviewCert] = useState<any>(null);
  const [schoolSettings, setSchoolSettings] = useState<any>(null);

  const dateInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const qCourses = query(collection(db, 'cursos'), orderBy('createdAt', 'desc'));
        const snapCourses = await getDocs(qCourses);
        setCourses(snapCourses.docs.map(doc => ({ id: doc.id, ...doc.data() } as Course)));

        const qStudents = query(collection(db, 'users'), where('role', '==', 'aluno'));
        const snapStudents = await getDocs(qStudents);
        setTotalStudents(snapStudents.size);

        if (auth.currentUser) {
          const directorDoc = await getDoc(doc(db, 'users', auth.currentUser.uid));
          if (directorDoc.exists()) setSchoolSettings(directorDoc.data());
        }

        const qCerts = query(collection(db, 'certificates'), orderBy('issuedAt', 'desc'));
        const snapCerts = await getDocs(qCerts);

        if (snapCerts.empty) {
          setCertificates([
            { id: 'EB-7721-A', studentName: 'Carlos Eduardo Silva', courseName: 'Teologia Sistemática I', issuedAt: new Date(2023, 11, 15), professorName: 'Prof. Dr. Arnaldo', code: 'VALID-990' },
            { id: 'EB-7722-B', studentName: 'Maria das Graças', courseName: 'História do Cristianismo', issuedAt: new Date(2024, 0, 10), professorName: 'Prof. Lucas Mendes', code: 'VALID-991' },
            { id: 'EB-7723-C', studentName: 'Ricardo Oliveira', courseName: 'Hermenêutica Avançada', issuedAt: new Date(2024, 2, 5), professorName: 'Prof. Paulo Silas', code: 'VALID-992' },
          ]);
        } else {
          setCertificates(snapCerts.docs.map(d => ({ id: d.id, ...d.data(), issuedAt: d.data().issuedAt?.toDate() })));
        }

      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const filteredAllCourses = useMemo(() => {
    return courses.filter(c => 
      c.nome.toLowerCase().includes(searchTerm.toLowerCase()) ||
      c.professorResponsavel.toLowerCase().includes(searchTerm.toLowerCase()) ||
      c.categoria.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [courses, searchTerm]);

  const filteredCerts = useMemo(() => {
    let list = certificates.filter(c => 
      c.studentName.toLowerCase().includes(certFilter.toLowerCase()) || 
      c.id.toLowerCase().includes(certFilter.toLowerCase())
    );

    const now = new Date();
    if (dateRange === '30') {
      const thirtyDaysAgo = new Date();
      thirtyDaysAgo.setDate(now.getDate() - 30);
      list = list.filter(c => c.issuedAt >= thirtyDaysAgo);
    } else if (dateRange === '90') {
      const ninetyDaysAgo = new Date();
      ninetyDaysAgo.setDate(now.getDate() - 90);
      list = list.filter(c => c.issuedAt >= ninetyDaysAgo);
    } else if (dateRange === 'custom' && customDate) {
      const selected = new Date(customDate);
      list = list.filter(c => 
        c.issuedAt.getFullYear() === selected.getFullYear() &&
        c.issuedAt.getMonth() === selected.getMonth() &&
        c.issuedAt.getDate() === selected.getDate()
      );
    }
    return list;
  }, [certificates, certFilter, dateRange, customDate]);

  const exportCoursesToCSV = () => {
    if (filteredAllCourses.length === 0) {
      alert("Não há dados para exportar.");
      return;
    }
    const headers = ["ID", "Nome da Disciplina", "Professor Titular", "Inscritos", "Categoria", "Nível", "Status"];
    const rows = filteredAllCourses.map(c => [
      c.id,
      `"${c.nome.replace(/"/g, '""')}"`,
      `"${c.professorResponsavel.replace(/"/g, '""')}"`,
      c.inscritos,
      c.categoria,
      c.nivelDificuldade,
      c.status
    ]);
    const csvContent = [headers, ...rows].map(e => e.join(",")).join("\n");
    const blob = new Blob(["\ufeff" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    const url = URL.createObjectURL(blob);
    link.setAttribute("href", url);
    link.setAttribute("download", `Matriz_Academica_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handlePrintAction = (cert: any) => {
    setPreviewCert(cert);
    setTimeout(() => window.print(), 300);
  };

  const handleDownloadAction = (cert: any) => {
    setPreviewCert(cert);
    setTimeout(() => window.print(), 300);
  };

  const openCourseReport = (course: Course) => {
    setSelectedCourse(course);
    setSubView('course_details');
  };

  if (loading && subView === 'main') {
    return (
      <div className="h-full flex items-center justify-center p-20">
        <div className="h-8 w-8 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div>
      </div>
    );
  }

  // --- VIEW: DETALHES DO CURSO (DASHBOARD DA DISCIPLINA) ---
  if (subView === 'course_details' && selectedCourse) {
    return (
      <div className="space-y-6 animate-in slide-in-from-right duration-500 pb-10">
        <header className="flex items-center gap-4">
          <button onClick={() => setSubView('main')} className="p-2 hover:bg-slate-200 rounded-full transition-colors bg-white shadow-sm border border-slate-200"><ArrowLeft size={20}/></button>
          <div>
            <h1 className="text-2xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">{selectedCourse.nome}</h1>
            <p className="text-indigo-600 text-[10px] font-black uppercase tracking-[0.2em] mt-1">ID: {selectedCourse.id} • Prof. {selectedCourse.professorResponsavel}</p>
          </div>
        </header>

        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
           {[
             { label: 'Matrículas Totais', value: selectedCourse.inscritos, icon: <Users size={20}/>, color: 'indigo' },
             { label: 'Nível Acadêmico', value: selectedCourse.nivelDificuldade, icon: <BarChart3 size={20}/>, color: 'amber' },
             { label: 'Certificados Emitidos', value: certificates.filter(c => c.courseName === selectedCourse.nome).length, icon: <FileBadge size={20}/>, color: 'emerald' },
             { label: 'Engajamento Médio', value: '94.2%', icon: <Activity size={20}/>, color: 'rose' }
