export default DashboardView;

import React, { useState, useEffect, useMemo } from 'react';
import { collection, query, getDocs, orderBy, where, doc, getDoc, onSnapshot } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { Course, MainView, ProfessorSubView, Module } from '../types';
import { 
  Users, FileBadge, Activity, ArrowUpRight, TrendingUp, Tv, ArrowLeft, 
  Search, Download, BookOpen, ChevronRight, ShieldCheck,
  Eye, X, Layers, Award, Target, Zap, Map as MapIcon, PlayCircle, Star,
  FileText
} from 'lucide-react';

interface DashboardViewProps {
  onNavigate: (main: MainView, sub?: ProfessorSubView) => void;
}

type DashboardSubView = 'main' | 'all_courses' | 'course_details' | 'certificates';

const DashboardView: React.FC<DashboardViewProps> = ({ onNavigate }) => {
  const [courses, setCourses] = useState<Course[]>([]);
  const [totalStudents, setTotalStudents] = useState(0);
  const [loading, setLoading] = useState(true);
  const [subView, setSubView] = useState<DashboardSubView>('main');
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Real Production Data
  const [realModules, setRealModules] = useState<Module[]>([]);
  const [realCertificates, setRealCertificates] = useState<any[]>([]);
  const [allFeedbacks, setAllFeedbacks] = useState<any[]>([]);
  const [showMindMap, setShowMindMap] = useState(false);
  const [previewCert, setPreviewCert] = useState<any>(null);
  const [showCertBack, setShowCertBack] = useState(false);
  const [schoolSettings, setSchoolSettings] = useState<any>(null);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const qCourses = query(collection(db, 'cursos'), orderBy('createdAt', 'desc'));
        const unsubscribeCourses = onSnapshot(qCourses, (snap) => {
          setCourses(snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as Course)));
        });

        const qStudents = query(collection(db, 'users'), where('role', '==', 'aluno'));
        const snapStudents = await getDocs(qStudents);
        setTotalStudents(snapStudents.size);

        if (auth.currentUser) {
          const directorDoc = await getDoc(doc(db, 'users', auth.currentUser.uid));
          if (directorDoc.exists()) setSchoolSettings(directorDoc.data());
        }

        const qCerts = query(collection(db, 'certificates'), orderBy('issuedAt', 'desc'));
        const unsubscribeCerts = onSnapshot(qCerts, (snap) => {
          setRealCertificates(snap.docs.map(d => ({ id: d.id, ...d.data(), issuedAt: d.data().issuedAt?.toDate() })));
        });

        const qFeedbacks = query(collection(db, 'feedbacks'));
        const unsubscribeFeedbacks = onSnapshot(qFeedbacks, (snap) => {
          setAllFeedbacks(snap.docs.map(d => d.data()));
        });

        setLoading(false);
        return () => {
          unsubscribeCourses();
          unsubscribeCerts();
          unsubscribeFeedbacks();
        };
      } catch (err) {
        console.error(err);
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    if (selectedCourse) {
      const qModules = query(collection(db, 'modulos'), where('courseId', '==', selectedCourse.id), orderBy('order', 'asc'));
      const unsubscribe = onSnapshot(qModules, (snap) => {
        setRealModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)));
      });
      return () => unsubscribe();
    }
  }, [selectedCourse]);

  const globalEngagement = useMemo(() => {
    if (allFeedbacks.length === 0) return '0%';
    const avg = allFeedbacks.reduce((acc, curr) => acc + (curr.rating || 0), 0) / allFeedbacks.length;
    return `${((avg / 5) * 100).toFixed(0)}%`;
  }, [allFeedbacks]);

  const openCourseReport = (course: Course) => {
    setSelectedCourse(course);
    setSubView('course_details');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const exportToExcel = () => {
    if (!selectedCourse) return;
    const headers = ["Modulo", "Aula", "Descricao", "Video URL"];
    const rows = realModules.flatMap(m => 
      m.lessons.map(l => [m.title, l.title, l.description || "", l.videoUrl])
    );

    let csvContent = "data:text/csv;charset=utf-8," 
      + headers.join(",") + "\n"
      + rows.map(e => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `relatorio_${selectedCourse.nome.replace(/\s+/g, '_')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const MindMapOverlay = () => (
    <div className="fixed inset-0 z-[1000] bg-slate-950/98 backdrop-blur-3xl p-6 md:p-10 overflow-auto flex flex-col items-center animate-in fade-in zoom-in-95">
      <header className="w-full flex justify-between items-center mb-10 max-w-6xl">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-xl"><MapIcon size={24}/></div>
          <div>
            <h2 className="text-xl font-black text-white uppercase italic tracking-tighter">Cronograma & Grade Curricular</h2>
            <p className="text-indigo-400 text-[8px] font-black uppercase tracking-[0.3em]">Módulos, Aulas e Avaliações</p>
          </div>
        </div>
        <button onClick={() => setShowMindMap(false)} className="p-3 bg-white/10 hover:bg-rose-600 text-white rounded-full transition-all"><X size={20}/></button>
      </header>

      <div className="relative flex flex-col items-center gap-16 w-full max-w-4xl pb-20">
