export default DashboardView;

import React, { useState, useEffect, useMemo } from 'react';
import { collection, query, getDocs, orderBy, where, doc, getDoc, onSnapshot } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { Course, MainView, ProfessorSubView, Module } from '../types';
import { 
  Users, FileBadge, Activity, ArrowUpRight, TrendingUp, Tv, ArrowLeft, 
  Search, Download, BookOpen, ChevronRight, ShieldCheck,
  Eye, X, Layers, Award, Target, Zap, Map as MapIcon, PlayCircle, Star,
  FileText, MessageCircle
} from 'lucide-react';

interface DashboardViewProps {
  onNavigate: (main: MainView, sub?: ProfessorSubView) => void;
}

type DashboardSubView = 'main' | 'all_courses' | 'course_details' | 'certificates';

const DashboardView: React.FC<DashboardViewProps> = ({ onNavigate }) => {
  const [courses, setCourses] = useState<Course[]>([]);
  const [totalStudents, setTotalStudents] = useState(0);
  const [loading, setLoading] = useState(true);
  const [subView, setSubView] = useState<DashboardSubView>('main');
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Real Production Data
  const [realModules, setRealModules] = useState<Module[]>([]);
  const [realCertificates, setRealCertificates] = useState<any[]>([]);
  const [allFeedbacks, setAllFeedbacks] = useState<any[]>([]);
  const [showMindMap, setShowMindMap] = useState(false);
  const [previewCert, setPreviewCert] = useState<any>(null);
  const [showCertBack, setShowCertBack] = useState(false);
  const [schoolSettings, setSchoolSettings] = useState<any>(null);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const qCourses = query(collection(db, 'cursos'), orderBy('createdAt', 'desc'));
        const unsubscribeCourses = onSnapshot(qCourses, (snap) => {
          setCourses(snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as Course)));
        });

        const qStudents = query(collection(db, 'users'), where('role', '==', 'aluno'));
        const snapStudents = await getDocs(qStudents);
        setTotalStudents(snapStudents.size);

        if (auth.currentUser) {
          const directorDoc = await getDoc(doc(db, 'users', auth.currentUser.uid));
          if (directorDoc.exists()) setSchoolSettings(directorDoc.data());
        }

        const qCerts = query(collection(db, 'certificates'), orderBy('issuedAt', 'desc'));
        const unsubscribeCerts = onSnapshot(qCerts, (snap) => {
          setRealCertificates(snap.docs.map(d => ({ id: d.id, ...d.data(), issuedAt: d.data().issuedAt?.toDate() })));
        });

        const qFeedbacks = query(collection(db, 'feedbacks'));
        const unsubscribeFeedbacks = onSnapshot(qFeedbacks, (snap) => {
          setAllFeedbacks(snap.docs.map(d => d.data()));
        });

        setLoading(false);
        return () => {
          unsubscribeCourses();
          unsubscribeCerts();
          unsubscribeFeedbacks();
        };
      } catch (err) {
        console.error(err);
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    if (selectedCourse) {
      const qModules = query(collection(db, 'modulos'), where('courseId', '==', selectedCourse.id), orderBy('order', 'asc'));
      const unsubscribe = onSnapshot(qModules, (snap) => {
        setRealModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)));
      });
      return () => unsubscribe();
    }
  }, [selectedCourse]);

  const globalEngagement = useMemo(() => {
    if (allFeedbacks.length === 0) return '0%';
    const avg = allFeedbacks.reduce((acc, curr) => acc + (curr.rating || 0), 0) / allFeedbacks.length;
    return `${((avg / 5) * 100).toFixed(0)}%`;
  }, [allFeedbacks]);

  const openCourseReport = (course: Course) => {
    setSelectedCourse(course);
    setSubView('course_details');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const exportToExcel = () => {
    if (!selectedCourse) return;
    const headers = ["Modulo", "Aula", "Descricao", "Video URL"];
    const rows = realModules.flatMap(m => 
      m.lessons.map(l => [m.title, l.title, l.description || "", l.videoUrl])
    );

    let csvContent = "data:text/csv;charset=utf-8," 
      + headers.join(",") + "\n"
      + rows.map(e => e.join(",")).join("\n");

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `relatorio_${selectedCourse.nome.replace(/\s+/g, '_')}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const MindMapOverlay = () => (
    <div className="fixed inset-0 z-[1000] bg-slate-950/98 backdrop-blur-3xl p-6 md:p-10 overflow-auto flex flex-col items-center animate-in fade-in zoom-in-95">
      <header className="w-full flex justify-between items-center mb-10 max-w-6xl">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-xl"><MapIcon size={24}/></div>
          <div>
            <h2 className="text-xl font-black text-white uppercase italic tracking-tighter">Cronograma & Grade Curricular</h2>
            <p className="text-indigo-400 text-[8px] font-black uppercase tracking-[0.3em]">Módulos, Aulas e Avaliações</p>
          </div>
        </div>
        <button onClick={() => setShowMindMap(false)} className="p-3 bg-white/10 hover:bg-rose-600 text-white rounded-full transition-all"><X size={20}/></button>
      </header>

      <div className="relative flex flex-col items-center gap-16 w-full max-w-4xl pb-20">
        <div className="bg-indigo-600 p-6 rounded-2xl text-white shadow-2xl border-2 border-white/20 z-10 text-center w-60">
           <h3 className="font-black italic uppercase tracking-tight text-sm">Início da Disciplina</h3>
        </div>

        {realModules.map((mod, idx) => (
          <div key={mod.id} className="relative flex flex-col items-center w-full">
            <div className="absolute -top-16 w-0.5 h-16 bg-indigo-500/30"></div>
            <div className="bg-white p-6 rounded-3xl shadow-xl border border-slate-100 w-full">
               <div className="flex items-center gap-3 mb-4">
                  <span className="bg-slate-900 text-indigo-400 w-8 h-8 rounded-lg flex items-center justify-center font-black text-xs italic">0{idx+1}</span>
                  <h4 className="text-slate-900 font-black text-base uppercase italic tracking-tighter">{mod.title}</h4>
               </div>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                  {mod.lessons?.map((lesson) => (
                    <div key={lesson.id} className="bg-slate-50 p-3 rounded-xl border border-slate-100 flex items-center gap-3">
                       <PlayCircle size={14} className="text-indigo-600" />
                       <span className="text-[10px] font-bold text-slate-600 uppercase italic truncate">{lesson.title}</span>
                    </div>
                  ))}
               </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );

  const CertificatePreview = ({ cert }: { cert: any }) => (
    <div className="fixed inset-0 z-[2000] bg-slate-950/95 backdrop-blur-xl flex items-center justify-center p-4 animate-in fade-in zoom-in-95 print:p-0 print:bg-white overflow-y-auto">
      <div className="bg-white w-full max-w-5xl aspect-[1.414/1] rounded-[2rem] shadow-2xl relative overflow-hidden flex flex-col p-12 border-8 border-double border-slate-100 print:rounded-none print:shadow-none print:border-none print:m-0 print:static print:w-full">
        <button onClick={() => setPreviewCert(null)} className="absolute top-6 right-6 p-2 bg-slate-100 rounded-full hover:bg-rose-100 transition-all print:hidden z-50"><X size={20}/></button>
        <button onClick={() => setShowCertBack(!showCertBack)} className="absolute bottom-6 right-6 px-6 py-3 bg-indigo-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-slate-900 transition-all print:hidden z-50">
           {showCertBack ? 'Frente' : 'Verso Acadêmico'}
        </button>

        {!showCertBack ? (
          <div className="relative z-10 flex-1 flex flex-col items-center justify-center text-center space-y-8">
             <h2 className="text-3xl font-black text-slate-900 uppercase tracking-widest italic">{schoolSettings?.certConfig?.schoolName || 'Escola Bíblica EAD'}</h2>
             <p className="text-4xl font-black text-slate-900 tracking-tighter uppercase italic">{cert.studentName}</p>
             <p className="text-xl font-bold text-slate-700 uppercase italic">Concluiu o curso de {cert.courseName}</p>
             <div className="w-full flex justify-around items-end pt-10">
                <div className="text-center"><div className="h-12 w-48 border-b border-slate-200 mb-2"></div><p className="text-[9px] font-black">DIRETOR ACADÊMICO</p></div>
                <div className="text-center"><div className="h-12 w-48 border-b border-slate-200 mb-2"></div><p className="text-[9px] font-black">PROFESSOR TITULAR</p></div>
             </div>
          </div>
        ) : (
          <div className="relative z-10 flex-1 flex flex-col p-6 bg-slate-50/30">
             <h3 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter mb-8 border-b pb-4">Histórico Acadêmico</h3>
             <div className="grid grid-cols-2 gap-8">
                <div className="space-y-4">
                   {realModules.map((m, idx) => (
                    <div key={m.id} className="flex justify-between text-[10px] font-bold border-b pb-2">
                       <span className="uppercase">MOD {idx+1}: {m.title}</span>
                       <span className="text-slate-400">APROVADO</span>
                    </div>
                   ))}
                </div>
                <div className="bg-white p-6 rounded-2xl border border-slate-100 space-y-4 shadow-sm">
                   <p className="text-[9px] font-bold">CARGA HORÁRIA: 40H</p>
                   <p className="text-[9px] font-bold">FREQUÊNCIA: 100%</p>
                   <p className="text-[9px] font-bold">AUTENTICAÇÃO: {cert.code || cert.id}</p>
                </div>
             </div>
          </div>
        )}
      </div>
    </div>
  );

  if (subView === 'course_details' && selectedCourse) {
    const courseCerts = realCertificates.filter(c => c.courseName === selectedCourse.nome).length;
    return (
      <div className="space-y-6 animate-in fade-in duration-500 pb-20">
        {showMindMap && <MindMapOverlay />}
        <header className="flex items-center justify-between bg-white p-6 rounded-[2rem] border border-slate-200">
          <div className="flex items-center gap-4">
            <button onClick={() => setSubView('main')} className="p-2 hover:bg-slate-100 rounded-full"><ArrowLeft size={20}/></button>
            <div>
              <h1 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter">{selectedCourse.nome}</h1>
              <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{selectedCourse.categoria}</p>
            </div>
          </div>
          <button onClick={exportToExcel} className="px-6 py-3 bg-slate-900 text-white rounded-xl text-[9px] font-black uppercase tracking-widest flex items-center gap-2 italic hover:bg-emerald-600 transition-all">
            <Download size={16}/> Exportar para Excel
          </button>
        </header>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-1 bg-white p-8 rounded-[2.5rem] border border-slate-200 text-center space-y-6">
            <div className="w-32 h-32 rounded-3xl overflow-hidden mx-auto border-4 border-slate-50 shadow-xl">
              <img src={selectedCourse.fotoDocenteUrl || 'https://via.placeholder.com/150'} className="w-full h-full object-cover" />
            </div>
            <h3 className="text-lg font-black text-slate-900 uppercase italic">{selectedCourse.professorResponsavel}</h3>
            <p className="text-[10px] text-slate-500 italic leading-relaxed">{selectedCourse.biografiaDocente || 'Perfil acadêmico vinculado.'}</p>
          </div>

          <div className="lg:col-span-2 space-y-6">
            <div className="grid grid-cols-3 gap-4">
              <div className="bg-white p-6 rounded-[2rem] border border-slate-200 text-center"><p className="text-[8px] font-black text-slate-400 uppercase mb-2 italic">Inscritos</p><p className="text-2xl font-black">{selectedCourse.inscritos}</p></div>
              <div className="bg-white p-6 rounded-[2rem] border border-slate-200 text-center"><p className="text-[8px] font-black text-slate-400 uppercase mb-2 italic">Diplomados</p><p className="text-2xl font-black">{courseCerts}</p></div>
              <div className="bg-white p-6 rounded-[2rem] border border-slate-200 text-center"><p className="text-[8px] font-black text-slate-400 uppercase mb-2 italic">Aprovação</p><p className="text-2xl font-black">94%</p></div>
            </div>
            <div className="bg-white rounded-[2rem] border border-slate-200 overflow-hidden">
               <div className="p-6 border-b flex items-center justify-between"><h3 className="text-[10px] font-black uppercase italic tracking-widest">Grade Curricular</h3><button onClick={() => setShowMindMap(true)} className="text-[9px] font-black text-indigo-600 uppercase flex items-center gap-2"><MapIcon size={14}/> Mapa Acadêmico</button></div>
               <div className="p-4 space-y-3">
                  {realModules.map((m, i) => (
                    <div key={m.id} className="p-4 bg-slate-50 rounded-xl flex items-center justify-between">
                       <span className="text-[10px] font-black uppercase italic">0{i+1} - {m.title}</span>
                       <span className="text-[8px] font-bold text-slate-400 uppercase">{m.lessons.length} Aulas</span>
                    </div>
                  ))}
               </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (subView === 'certificates') {
    return (
      <div className="space-y-6 animate-in slide-in-from-right duration-500">
        {previewCert && <CertificatePreview cert={previewCert} />}
        <header className="flex items-center gap-4">
          <button onClick={() => setSubView('main')} className="p-2 hover:bg-slate-100 rounded-full transition-colors bg-white shadow-sm border border-slate-200"><ArrowLeft size={20}/></button>
          <div><h1 className="text-2xl font-black text-slate-900 uppercase tracking-tighter italic">Arquivo de Certificações</h1><p className="text-slate-500 text-sm font-medium italic">Registros oficiais emitidos.</p></div>
        </header>
        <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic">
              <tr><th className="px-8 py-5">Identificação</th><th className="px-8 py-5">Aluno</th><th className="px-8 py-5">Curso</th><th className="px-8 py-5 text-center">Ações</th></tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {realCertificates.map(c => (
                <tr key={c.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-8 py-5 font-black text-slate-900 text-xs italic">{c.code || c.id}</td>
                  <td className="px-8 py-5 font-bold text-slate-600 text-xs uppercase italic">{c.studentName}</td>
                  <td className="px-8 py-5 font-bold text-slate-400 text-xs italic">{c.courseName}</td>
                  <td className="px-8 py-5 text-center"><button onClick={() => setPreviewCert(c)} className="p-2.5 bg-indigo-50 text-indigo-600 rounded-xl"><Eye size={14}/></button></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    );
  }

  if (subView === 'all_courses') {
    return (
      <div className="space-y-6 animate-in slide-in-from-right duration-500">
        <header className="flex items-center gap-4">
          <button onClick={() => setSubView('main')} className="p-2 hover:bg-slate-100 rounded-full transition-colors bg-white shadow-sm border border-slate-200"><ArrowLeft size={20}/></button>
          <div><h1 className="text-2xl font-black text-slate-900 uppercase tracking-tighter italic">Matriz Acadêmica Completa</h1><p className="text-slate-500 text-sm font-medium italic">Todos os cursos da institution.</p></div>
        </header>
        <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden">
          <div className="p-8 border-b border-slate-100 bg-slate-50/50">
             <div className="relative w-full max-w-md">
                <Search size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Pesquisar..." className="w-full pl-12 pr-4 py-3 border rounded-2xl text-xs font-bold shadow-inner" />
             </div>
          </div>
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic">
              <tr><th className="px-8 py-5">Disciplina</th><th className="px-8 py-5">Status</th><th className="px-8 py-5 text-center">Relatório</th></tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {courses.filter(c => c.nome.toLowerCase().includes(searchTerm.toLowerCase())).map(c => (
                <tr key={c.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-8 py-5 font-black text-slate-900 text-xs italic uppercase">{c.nome}</td>
                  <td className="px-8 py-5"><span className="px-3 py-1 bg-emerald-50 text-emerald-600 rounded-lg text-[9px] font-black uppercase">{c.status}</span></td>
                  <td className="px-8 py-5 text-center"><button onClick={() => openCourseReport(c)} className="p-2.5 bg-indigo-50 text-indigo-600 rounded-xl"><ArrowUpRight size={16}/></button></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    );
  }

  const stats = [
    { label: 'Matrículas Ativas', value: totalStudents.toString(), icon: <Users size={20} />, trend: '+Produção', action: () => onNavigate('alunos') },
    { label: 'Diplomas Emitidos', value: realCertificates.length.toString(), icon: <FileBadge size={20} />, trend: 'Auditado', action: () => setSubView('certificates') },
    { label: 'Engajamento Global', value: globalEngagement, icon: <Activity size={20} />, trend: 'Real', action: () => onNavigate('professor', 'feedback') },
  ];

  return (
    <div className="space-y-6 animate-in fade-in duration-700">
      <header>
        <h1 className="text-3xl font-black text-slate-900 tracking-tight uppercase italic leading-none">Painel de Controle</h1>
        <p className="text-slate-500 text-sm font-medium mt-2 italic">Gerenciamento operacional e acadêmico unificado.</p>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {stats.map((stat, i) => (
          <div key={i} onClick={stat.action} className="bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm flex items-start justify-between group hover:border-indigo-400 hover:shadow-xl transition-all cursor-pointer">
            <div>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 italic">{stat.label}</p>
              <div className="flex items-baseline gap-3">
                <h3 className="text-4xl font-black text-slate-900 tracking-tighter tabular-nums">{stat.value}</h3>
                <span className="text-[10px] font-black text-emerald-600 flex items-center bg-emerald-50 px-3 py-1 rounded-full italic">{stat.trend}</span>
              </div>
            </div>
            <div className="p-5 bg-slate-50 text-slate-400 group-hover:bg-indigo-600 group-hover:text-white rounded-[1.5rem] shadow-inner transition-all duration-500">
              {stat.icon}
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col min-h-[500px]">
          <div className="px-10 py-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
            <div className="flex items-center gap-3">
               <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg"><BookOpen size={20}/></div>
               <h2 className="text-xs font-black text-slate-800 uppercase tracking-widest italic">Disciplinas Recentes</h2>
            </div>
            <button onClick={() => setSubView('all_courses')} className="text-[10px] font-black uppercase text-indigo-600 hover:bg-indigo-600 hover:text-white border border-indigo-200 px-6 py-3 rounded-2xl transition-all italic">Ver Matriz Completa</button>
          </div>
          <div className="flex-1 overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic">
                <tr><th className="px-10 py-5">Disciplina</th><th className="px-10 py-5">Matrículas</th><th className="px-10 py-5">Professor</th><th className="px-10 py-5"></th></tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {courses.slice(0, 6).map(c => (
                  <tr key={c.id} className="hover:bg-indigo-50/10 transition-colors group">
                    <td className="px-10 py-6"><span className="font-black text-slate-900 text-xs uppercase italic tracking-tight">{c.nome}</span></td>
                    <td className="px-10 py-6 font-black text-slate-600 text-xs tabular-nums">{c.inscritos} Alunos</td>
                    <td className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase italic">{c.professorResponsavel}</td>
                    <td className="px-10 py-6 text-right"><button onClick={() => openCourseReport(c)} className="p-3 text-slate-300 hover:text-indigo-600 hover:scale-110 transition-all"><ArrowUpRight size={18} /></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <div className="space-y-6">
           <div className="bg-slate-900 text-white p-10 rounded-[3rem] shadow-2xl relative overflow-hidden group">
              <div className="relative z-10">
                <div className="flex items-center gap-3 mb-6"><div className="w-2 h-2 bg-rose-500 rounded-full animate-ping"></div><h3 className="text-xs font-black uppercase tracking-widest italic">Live Classroom</h3></div>
                <h3 className="text-3xl font-black mb-2 uppercase tracking-tighter italic leading-none">Aulas Ao Vivo</h3>
                <p className="text-slate-400 text-[10px] font-medium mb-10 leading-relaxed uppercase tracking-widest italic">Transmissão em tempo real.</p>
                <button onClick={() => onNavigate('professor', 'live')} className="w-full bg-indigo-600 py-5 rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest hover:bg-indigo-500 transition-all italic"><Tv size={18} className="inline mr-2" /> Iniciar Aula</button>
              </div>
              <Tv size={180} className="absolute -bottom-10 -right-10 text-white/5" />
           </div>

           <div className="bg-white p-10 rounded-[3rem] border border-slate-200 shadow-sm space-y-8">
              <div className="flex items-center gap-3"><div className="p-2.5 bg-slate-900 text-white rounded-xl"><TrendingUp size={16}/></div><h3 className="text-xs font-black text-slate-800 uppercase tracking-widest italic">Atalhos Master</h3></div>
              <div className="space-y-3">
                 <button onClick={() => onNavigate('professor', 'relatorio')} className="w-full flex items-center justify-between px-8 py-5 rounded-2xl bg-slate-50 hover:bg-indigo-600 hover:text-white transition-all text-[10px] font-black uppercase italic group"><div className="flex items-center gap-2"><TrendingUp size={14} className="text-slate-400 group-hover:text-white" /> Desempenho Acadêmico Global</div> <ChevronRight size={14}/></button>
                 <button onClick={() => onNavigate('professor', 'feedback')} className="w-full flex items-center justify-between px-8 py-5 rounded-2xl bg-slate-50 hover:bg-indigo-600 hover:text-white transition-all text-[10px] font-black uppercase italic group"><div className="flex items-center gap-2"><MessageCircle size={14} className="text-slate-400 group-hover:text-white" /> Feedback Discente Ativo</div> <ChevronRight size={14}/></button>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default DashboardView;
